async count({ model, where }: CountParams): Promise<number> {
  const tbl = resolveTable(model);
  const { sql } = drizzleOps;
  const cond = buildWhere(drizzleOps, tbl, where);
  const rows = await db
    .select({ value: sql<number>`count(*)`.as('value') })
    .from(tbl)
    .where(cond)
    .execute();
  const v = rows?.[0]?.value;
  return typeof v === 'number' ? v : Number(v ?? 0);
},

async transaction<R>(fn: (trx: any) => Promise<R>): Promise<R> {
  // Drizzle's transaction API varies by dialect
  // For async dialects (postgres, mysql): db.transaction returns Promise
  // For better-sqlite3: db.transaction must be synchronous
  if (dialect === 'sqlite') {
    // better-sqlite3's `db.transaction(cb)` commits as soon as the
    // (synchronous) callback returns. An async callback returns a
    // pending Promise immediately, so the transaction would COMMIT
    // before any awaited operation ran — providing no atomicity and
    // making rollback impossible. Instead we drive the transaction
    // explicitly with BEGIN/COMMIT/ROLLBACK on the same connection.
    // Because the SQLite connection is single-threaded and serialized,
    // every operation issued via `txAdapter` between BEGIN and COMMIT
    // runs inside the transaction and is rolled back on error.
    const { sql } = drizzleOps;
    const child = drizzleAdapter({ ...config, db });
    const txAdapter: any = {
      ...child,
      transaction: async () => {
        throw new OperationNotSupportedError('transaction', 'DrizzleAdapter (nested transaction)');
      },
      close: async () => { },
      commit: async () => { },
      rollback: async () => { },
    };

    await db.run(sql`BEGIN`);
    try {
      const result = await fn(txAdapter);
      await db.run(sql`COMMIT`);
      return result;
    } catch (err) {
      try {
        await db.run(sql`ROLLBACK`);
      } catch {
        // Ignore rollback failures; surface the original error below.
      }
      throw err;
    }
  } else {
    // Async transaction for postgres/mysql
    return await db.transaction(async (trx: any) => {
      const child = drizzleAdapter({ ...config, db: trx });
      const txAdapter: any = {
        ...child,
        transaction: async () => {
          throw new OperationNotSupportedError('transaction', 'DrizzleAdapter (nested transaction)');
        },
        close: async () => { },
        commit: async () => { },
        rollback: async () => { },
      };
      return await fn(txAdapter);
    });
  }
},

